    74→    public function generateInvoice(Request $request, SchoolClass $kelas)
    75→    {
    76→        $request->validate([
    77→            'deskripsi'   => 'required|string|max:255',
    78→            'total'       => 'required|numeric|min:1000',
    79→            'jatuh_tempo' => 'required|date',
    80→        ]);
    81→
    82→        $student = $kelas->siswa()->first();
    83→        if (!$student) {
    84→            return back()->with('error', 'Tidak ada siswa di kelas ini.');
    85→        }
    86→
    87→        $year  = date('Y');
    88→        $month = str_pad(date('m'), 2, '0', STR_PAD_LEFT);
    89→        $count = Invoice::whereYear('created_at', $year)->whereMonth('created_at', date('m'))->count() + 1;
    90→        $nomor = 'INV-' . $year . '-' . $month . str_pad($count, 3, '0', STR_PAD_LEFT);
    91→
    92→        Invoice::create([
    93→            'siswa_id'      => $student->id,
    94→            'cabang_id'     => $kelas->cabang_id,
    95→            'nomor_invoice' => $nomor,
    96→            'deskripsi'     => $request->deskripsi,
    97→            'subtotal'      => $request->total,
    98→            'diskon'        => 0,
    99→            'pajak'         => 0,
   100→            'total'         => $request->total,
   101→            'status'        => 'belum_bayar',
   102→            'jatuh_tempo'   => $request->jatuh_tempo,
   103→            'periode'       => date('Y-m'),
   104→        ]);
   105→
   106→        return back()->with('success', 'Invoice berhasil dibuat.');
   107→    }
   108→}
